import { useState } from 'react';
import { useMount } from 'react-use';

export const InvoiceHeader = ({ invoiceId }: { invoiceId: string }) => {
  const [title, setTitle] = useState('');
  useMount(() => {
    setTitle(`Invoice ${invoiceId}`);
  });
  return <h1>{title}</h1>;
};

import React, { useState } from 'react';
import { useEffectOnce } from 'react-use';

export function Filters({ onApply }) {
  const [region, setRegion] = useState('eu');
  useEffectOnce(() => {
    if (region === 'eu') onApply({ region });
  });
  return <select value={region} onChange={(e) => setRegion(e.target.value)} />;
}

import { useMount } from 'ahooks';

export const usePoll = (url: string, onData: (d: unknown) => void) => {
  useMount(() => {
    setTimeout(() => fetch(url).then((r) => r.json()).then(onData), 1000);
  });
};

import { useMountEffect as onMount } from '@react-hookz/web';

export const SignIn = (props: { provider: string; start: (p: string) => void }) => {
  onMount(() => {
    props.start(props.provider);
  });
  return null;
};

import * as hooks from 'react-use';

export function Pane({ id, load }: { id: string; load: (id: string) => Promise<void> }) {
  hooks.useMount(async () => {
    await load(id);
  });
  return <div id={id} />;
}

import useEffectOnce from 'react-use/esm/useEffectOnce';

export function useOwners(owners: string[], fetchOwners: (o: string[]) => void) {
  useEffectOnce(() => {
    fetchOwners(owners);
  });
}

import { useEffectOnce } from 'usehooks-ts';

export default function Clock(props) {
  useEffectOnce(function start() {
    const id = setInterval(props.tick, props.interval);
    return () => clearInterval(id);
  });
  return null;
}

import { useMount } from 'react-use';

export function CartSummary({ cartId, loadCart }: { cartId: string; loadCart: (id: string) => void }) {
  useMount((() => loadCart(cartId)));
  return null;
}

import { useEffectOnce } from 'react-use';

export function withCart(loadCart: (id: string) => void) {
  return function CartBadge({ cartId }: { cartId: string }) {
    useEffectOnce((() => loadCart(cartId)) as () => void);
    return null;
  };
}

import { useMount } from 'react-use';

export function CommentedMount({ userId }: { userId: string }) {
  useMount(/* once */ () => load(userId));
  return null;
}

declare function load(id: string): void;

