import { useEffect, useState } from 'react';

export const InvoiceHeader = ({ invoiceId }: { invoiceId: string }) => {
  const [title, setTitle] = useState('');
  useEffect(() => {
    setTitle(`Invoice ${invoiceId}`);
  }, [invoiceId]);
  return <h1>{title}</h1>;
};

import { useDidUpdate } from './hooks/useDidUpdate';

export function ArrayField({ value, onCollapse }: { value: string[]; onCollapse: () => void }) {
  useDidUpdate(value.length, (prev, next) => {
    if (next < prev) onCollapse();
  });
  return null;
}

import { useUnmount } from 'react-use';

export function Draft({ text, save }: { text: string; save: (t: string) => void }) {
  useUnmount(() => save(text));
  return <textarea defaultValue={text} />;
}

import { useMount } from 'react-use';
import { refreshModels } from '../api/models';

export function ModelPicker() {
  useMount(refreshModels);
  useMount(() => {
    void refreshModels();
  });
  return null;
}

import { useRef, useState } from 'react';
import { useEffectOnce } from 'react-use';

export function Measure() {
  const box = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);
  useEffectOnce(() => {
    setWidth(box.current?.offsetWidth ?? 0);
  });
  return <div ref={box}>{width}</div>;
}

import { useMount } from 'react-use';

export function ChangePassword({ loadUser }: { loadUser: () => void }) {
  useMount(() => loadUser());
  return null;
}

import { useIsomorphicLayoutEffect } from 'usehooks-ts';
import { useMountedState, useFirstMountState } from 'react-use';

export function Portal({ target }: { target: string }) {
  const isMounted = useMountedState();
  const first = useFirstMountState();
  useIsomorphicLayoutEffect(() => {
    document.title = target;
  }, [target]);
  return first && isMounted() ? null : null;
}

import { useMountEffect } from '@react-hookz/web';
import { useAsyncFn } from './useAsyncFn';

export function Redirect({ api }: { api: { start(): Promise<string> } }) {
  const [state, execute] = useAsyncFn(() => api.start());
  const actions = { execute };
  useMountEffect(execute);
  useMountEffect(actions.execute);
  return state.loading ? null : <form />;
}

import { useState } from 'react';
import { useDidUpdate } from '@mantine/hooks';
import { useUpdateEffect } from 'react-use';

export function OrderBy({ input, alias }: { input: string; alias: string }) {
  const [explain, setExplain] = useState({ input, alias });
  useDidUpdate(() => {
    setExplain({ input: input ?? '', alias });
  }, [input, alias]);
  useUpdateEffect(() => {
    setExplain((prev) => ({ ...prev, alias: '' }));
  }, [input]);
  return <span>{explain.input}</span>;
}

import { useUpdateEffect } from 'ahooks';

export function Pager({ page, size, onPage }: { page: number; size: number; onPage: (p: number, s: number) => void }) {
  useUpdateEffect(() => {
    onPage(page, size);
  }, [page]);
  return <span>{page}</span>;
}

import { useDidUpdate } from '@mantine/hooks';

export function Field({ active, label, focusInput }: { active: boolean; label: string; focusInput: (l: string) => void }) {
  useDidUpdate(() => {
    if (active) focusInput(label);
  }, [active]);
  return <label>{label}</label>;
}

import { useMount } from 'react-use';
import { useComposer } from './useComposer';

export function Composer() {
  const { inputRef } = useComposer();
  useMount(() => {
    inputRef.current?.focus();
  });
  return <textarea ref={inputRef} />;
}

import { useState } from 'react';
import { useEffectOnce } from 'react-use';

export const TagEditor = (props) => {
  const [tag, setTag] = useState(null);
  useEffectOnce(() => {
    setTag(parseTag(props.defaultValue));
  });
  return <span>{tag}</span>;
};

export function useOwnerFetch({ initialOwners, fetchOwners }) {
  useEffectOnce(() => {
    fetchOwners(initialOwners);
  });
}

import * as R from 'react';
import { useMount } from 'react-use';

const { useState: useLocalState } = R;

export function Size({ observe }: { observe: (el: unknown, cb: (w: number) => void) => void }) {
  const box = R.useRef<HTMLDivElement>(null);
  const [width, setWidth] = useLocalState(0);
  useMount(() => {
    observe(box, setWidth);
  });
  return <div ref={box}>{width}</div>;
}

